/**
 * `next-auth/providers` on denext: the provider types. Each provider is its own module
 * (`next-auth/providers/github`, `…/google`, `…/kakao`, `…/passkey`, `…/resend`, … — every one
 * `@auth/core` ships but the fourteen KNOWN-LIMITATIONS.md lists; the OAuth / OIDC ones denext has
 * no preset for are generated by `deno task gen:auth-providers`); a custom OAuth / OIDC provider is
 * a plain object (`{ id, name, type: "oauth", authorization, token, userinfo, … }`).
 *
 * @module
 */

export type { Provider } from "../types.ts";
export type {
  BuiltProvider,
  CustomOAuthConfig as OAuthConfig,
  EndpointConfig,
  EnvReader,
  OAuthUserConfig,
  ProfileUser,
  ProviderDescriptor,
} from "./shared.ts";
export type { CredentialInput, CredentialsConfig } from "./credentials.ts";
export type { EmailUserConfig, SendVerificationRequestParams } from "./email-shared.ts";
export type { NodemailerUserConfig, SmtpServerOptions } from "./nodemailer.ts";
export type { ResendUserConfig } from "./resend.ts";
export type { GeneratedUserConfig } from "./generated.ts";
export type { HttpEmailUserConfig } from "./email-http.ts";
export type { WebAuthnCeremonyOptions, WebAuthnUserConfig } from "./webauthn-shared.ts";
